import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StringTokenizer st = new StringTokenizer(new String(System.in.readAllBytes()));
        int q = Integer.parseInt(st.nextToken());
        // Run length stored at each run's endpoints (and at each newly built house).
        HashMap<Integer, Integer> len = new HashMap<>(q * 4);
        int best = 0;
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < q; i++) {
            int x = Integer.parseInt(st.nextToken());
            int left = len.getOrDefault(x - 1, 0), right = len.getOrDefault(x + 1, 0);
            int length = left + right + 1;
            len.put(x, length);
            len.put(x - left, length);
            len.put(x + right, length);
            best = Math.max(best, length);
            if (i > 0) sb.append(' ');
            sb.append(best);
        }
        System.out.println(sb);
    }
}

package main

import (
	"bufio"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	next := func() int { sc.Scan(); v, _ := strconv.Atoi(sc.Text()); return v }
	q := next()
	// Run length stored at each run's endpoints (and at each newly built house).
	length := make(map[int]int, 2*q)
	best := 0
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	for i := 0; i < q; i++ {
		x := next()
		left, right := length[x-1], length[x+1]
		l := left + right + 1
		length[x], length[x-left], length[x+right] = l, l, l
		best = max(best, l)
		if i > 0 {
			w.WriteByte(' ')
		}
		w.WriteString(strconv.Itoa(best))
	}
	w.WriteByte('\n')
}
